const uint16_t palettes[] = {
  RGB(4,4,7),RGB(10,8,13),RGB(18,13,16),RGB(30,28,23),
  RGB(4,4,7),RGB(13,8,7),RGB(18,12,9),RGB(29,20,13),
  RGB(4,4,7),RGB(7,12,11),RGB(13,18,13),RGB(22,25,17),
